INSERT INTO `faq_items` (`id`, `question`, `answer`, `category`, `sort_order`, `published`, `created_at`) VALUES
(1, 'What payment methods do you accept?', 'We accept PayPal, Stripe, Square, Cash App, Apple Pay, Google Pay, Bitcoin, Ethereum, Litecoin, USDT, and bank transfers.', 'Payments', 1, 1, '2026-06-02 16:28:26'),
(2, 'How long does shipping take?', 'US standard shipping takes 5-8 business days. Express 2-3 days. International varies by region (7-21 days).', 'Shipping', 2, 1, '2026-06-02 16:28:26'),
(3, 'Do you ship internationally?', 'Yes, we ship to over 60 countries. International rates are calculated at checkout.', 'Shipping', 3, 1, '2026-06-02 16:28:26'),
(4, 'What is your return policy?', '30-day return policy for unworn items in original condition. Refunds processed within 5-7 business days.', 'Returns', 4, 1, '2026-06-02 16:28:26'),
(5, 'How do I track my order?', 'You will receive a tracking number via email. Track orders from your account dashboard.', 'Orders', 5, 1, '2026-06-02 16:28:26'),
(6, 'Can I change or cancel my order?', 'Orders can be modified within 1 hour of placement. Contact support immediately.', 'Orders', 6, 1, '2026-06-02 16:28:26'),
(7, 'Do you have a size guide?', 'Yes, each product page has a detailed size chart. General sizing runs true to size.', 'Products', 7, 1, '2026-06-02 16:28:26'),
(8, 'How do I use a discount code?', 'Enter your coupon code at checkout in the Discount Code field.', 'Orders', 8, 1, '2026-06-02 16:28:26'),
(9, 'Is my payment information secure?', 'Yes. We use industry-standard encryption and never store full credit card numbers.', 'Security', 9, 1, '2026-06-02 16:28:26'),
(10, 'Do you have a loyalty program?', 'Coming soon! We are developing a loyalty rewards program.', 'Account', 10, 1, '2026-06-02 16:28:26'),
