INSERT INTO `pages` (`id`, `title`, `slug`, `content`, `meta_title`, `meta_description`, `published`, `created_at`, `updated_at`) VALUES
(1, 'About SUGGAWAYZ', 'about', '<h2>The Future of Streetwear</h2><p>SUGGAWAYZ was founded on the belief that clothing should be more than fabric. We bridge the gap between cyberpunk aesthetics and everyday wearability.</p><p>Every piece is designed with meticulous attention to detail, using premium materials and innovative construction techniques.</p><p>We are not just a clothing brand. We are a movement.</p>', NULL, NULL, 1, '2026-06-02 16:28:26', '2026-06-02 16:28:26'),
(2, 'Terms & Conditions', 'terms', '<h2>Terms of Service</h2><p>By accessing and using the SUGGAWAYZ website and services, you agree to be bound by these terms.</p><h3>Orders</h3><p>All orders are subject to acceptance and availability. We reserve the right to cancel any order.</p><h3>Pricing</h3><p>All prices are in USD and subject to change without notice. Sale prices apply at the time of purchase.</p><h3>Shipping</h3><p>Shipping rates and estimated delivery times are calculated at checkout. We are not responsible for customs delays.</p><h3>Returns</h3><p>Items may be returned within 30 days of delivery in unused condition.</p>', NULL, NULL, 1, '2026-06-02 16:28:26', '2026-06-02 16:28:26'),
(3, 'Privacy Policy', 'privacy', '<h2>Privacy Policy</h2><p>SUGGAWAYZ respects your privacy. This policy outlines how we collect, use, and protect your personal information.</p><h3>Information We Collect</h3><p>We collect information you provide: name, email, shipping address, payment details. We also collect browsing data through cookies.</p><h3>How We Use Your Information</h3><p>We use your information to process orders, improve our store, send marketing communications, and prevent fraud.</p><h3>Data Security</h3><p>We implement industry-standard encryption and security measures. We do not sell your personal data.</p>', NULL, NULL, 1, '2026-06-02 16:28:26', '2026-06-02 16:28:26'),
(597, 'Returns & Exchanges', 'returns', '<h2>Returns & Exchanges</h2><p>We want you to love your purchase. If something isn\\\'t right, we\\\'re here to help.</p><h3>Return Policy</h3><p>Items may be returned within 30 days of delivery in unused, unworn condition with original tags attached.</p><h3>Refunds</h3><p>Refunds are processed within 5-7 business days after we receive your return. Shipping costs are non-refundable.</p><h3>Exchanges</h3><p>For size exchanges, please return the original item and place a new order. This ensures the fastest turnaround.</p><h3>Damaged or Incorrect Items</h3><p>If you received a damaged or incorrect item, contact us within 48 hours of delivery for a replacement.</p>', NULL, NULL, 1, '2026-06-02 17:15:56', '2026-06-02 17:15:56'),
(598, 'Size Guide', 'size-guide', '<h2>Size Guide</h2><p>Find your perfect fit.</p><h3>Tops</h3><p>Size chart coming soon.</p>', NULL, NULL, 1, '2026-06-02 17:15:56', '2026-06-02 17:15:56');
