INSERT INTO `products` (`id`, `name`, `sku`, `slug`, `description`, `short_description`, `seo_description`, `price`, `sale_price`, `cost_price`, `sizes`, `colors`, `images`, `videos`, `is_featured`, `is_new`, `status`, `category_id`, `meta_title`, `meta_description`, `created_at`, `updated_at`) VALUES
(1, 'Shadow Hoodie', 'SW-HOOD-001', 'shadow-hoodie', 'Heavyweight black cyberwear hoodie with blue chrome detailing and oversized streetwear fit. Features ribbed cuffs, adjustable drawcord hood, and premium fleece interior.', 'Premium black hoodie with cyber details.', 'Premium black SUGGAWAYZ Shadow Hoodie with futuristic blue details.', 89.99, NULL, NULL, '[\"S\", \"M\", \"L\", \"XL\", \"2XL\"]', '[\"Black\", \"Chrome Blue\"]', '[\"/assets/img/products/shadow-hoodie-1.png\", \"/assets/img/products/product-1-1780419566.jpg\"]', NULL, 1, 0, 'active', 1, NULL, NULL, '2026-06-02 16:28:26', '2026-06-02 16:59:26'),
(2, 'Cyber Tee', 'SW-TEE-002', 'cyber-tee', 'Soft graphic tee built for daily wear, drops, shows, and late-night city movement. Features screen-printed front graphic with reflective ink detailing.', 'Graphic tee with reflective detailing.', 'SUGGAWAYZ Cyber Tee futuristic streetwear graphic shirt.', 49.99, 39.99, NULL, '[\"S\", \"M\", \"L\", \"XL\"]', '[\"Black\", \"White\", \"Blue\"]', '[\"/assets/img/products/cyber-tee-1.png\"]', NULL, 1, 0, 'active', 2, NULL, NULL, '2026-06-02 16:28:26', '2026-06-02 16:28:26'),
(3, 'Future Jacket', 'SW-JKT-003', 'future-jacket', 'Structured techwear jacket with reflective panels, deep pockets, and storm-ready fabric. Water-resistant shell with breathable mesh lining.', 'Techwear jacket with reflective panels.', 'SUGGAWAYZ Future Jacket black techwear outerwear.', 149.99, NULL, NULL, '[\"M\", \"L\", \"XL\", \"2XL\"]', '[\"Black\", \"Graphite\"]', '[\"/assets/img/products/future-jacket-1.png\"]', NULL, 1, 0, 'active', 3, NULL, NULL, '2026-06-02 16:28:26', '2026-06-02 16:28:26'),
(4, 'Neon Joggers', 'SW-PNT-004', 'neon-joggers', 'Slim-fit joggers with neon reflective stripes, zip pockets, and elastic cuffs. Built for movement and style.', 'Slim joggers with neon stripes.', 'SUGGAWAYZ Neon Joggers street-ready bottoms.', 74.99, 59.99, NULL, '[\"S\", \"M\", \"L\", \"XL\"]', '[\"Black\", \"Gray\"]', '[\"/assets/img/products/neon-joggers-1.png\"]', NULL, 1, 0, 'active', 4, NULL, NULL, '2026-06-02 16:28:26', '2026-06-02 16:28:26'),
(5, 'Holographic Cap', 'SW-ACC-005', 'holographic-cap', 'Six-panel cap with holographic SUGGAWAYZ logo, adjustable strap, and breathable mesh back.', 'Holographic logo cap.', 'SUGGAWAYZ Holographic Cap accessory.', 34.99, NULL, NULL, '[\"OS\"]', '[\"Black\", \"White\"]', '[\"/assets/img/products/holo-cap-1.png\"]', NULL, 0, 0, 'active', 5, NULL, NULL, '2026-06-02 16:28:26', '2026-06-02 16:28:26'),
(6, 'Cybermask Pack', 'SW-ACC-006', 'cybermask', 'Reusable face mask with cyber print, filter pocket, and adjustable ear loops. Pack of 3.', 'Pack of 3 cyber print masks.', 'SUGGAWAYZ Cybermask pack accessories.', 24.99, 19.99, NULL, '[\"OS\"]', '[\"Black\", \"Blue\", \"White\"]', '[\"/assets/img/products/cybermask-1.png\"]', NULL, 0, 0, 'active', 5, NULL, NULL, '2026-06-02 16:28:26', '2026-06-02 16:28:26'),
(7, 'Cargo Tech Pants', 'SW-PNT-007', 'cargo-tech-pants', 'Technical cargo pants with 8 pockets, knee articulation, and DWR coating. Tapered fit with zip hem.', 'Technical cargo pants with 8 pockets.', 'SUGGAWAYZ Cargo Tech Pants streetwear bottoms.', 119.99, 89.99, NULL, '[\"S\", \"M\", \"L\", \"XL\", \"2XL\"]', '[\"Black\", \"Olive\"]', '[\"/assets/img/products/cargo-tech-1.png\"]', NULL, 1, 0, 'active', 4, NULL, NULL, '2026-06-02 16:28:26', '2026-06-02 16:28:26'),
(8, 'Neon Genesis Hoodie', 'SW-LTD-008', 'neon-genesis-hoodie', 'Limited edition run of 500. UV-reactive neon print on heavyweight black fleece. Each piece individually numbered.', 'Limited edition UV-reactive hoodie.', 'SUGGAWAYZ Neon Genesis limited drop hoodie.', 129.99, NULL, NULL, '[\"S\", \"M\", \"L\", \"XL\", \"2XL\"]', '[\"Black\"]', '[\"/assets/img/products/neon-genesis-1.png\"]', NULL, 1, 1, 'active', 6, NULL, NULL, '2026-06-02 16:28:26', '2026-06-02 16:28:26'),
(9, 'Phantom Mesh Tee', 'SW-TEE-009', 'phantom-mesh-tee', 'Breathable mesh tee with phantom gradient print. Perfect for layering or standalone wear.', 'Mesh tee with phantom gradient.', 'SUGGAWAYZ Phantom Mesh Tee.', 44.99, NULL, NULL, '[\"S\", \"M\", \"L\", \"XL\"]', '[\"Black\", \"White\"]', '[\"/assets/img/products/phantom-mesh-1.png\"]', NULL, 0, 1, 'active', 2, NULL, NULL, '2026-06-02 16:28:26', '2026-06-02 16:28:26'),
(10, 'Signal Blue Hoodie', 'SW-HOOD-010', 'signal-blue-hoodie', 'Vibrant signal blue hoodie with tonal embroidery and oversized cut. Made from 400gsm organic cotton fleece.', 'Signal blue oversized hoodie.', 'SUGGAWAYZ Signal Blue Hoodie.', 99.99, NULL, NULL, '[\"S\", \"M\", \"L\", \"XL\", \"2XL\"]', '[\"Signal Blue\"]', '[\"/assets/img/products/signal-blue-1.png\"]', NULL, 1, 1, 'active', 1, NULL, NULL, '2026-06-02 16:28:26', '2026-06-02 16:28:26');
